#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define V 50257
#define D 768
#define L 12
#define H 12
#define FF 3072
#define MAXSEQ 1024

static float *weights;
static char *vocab[V];
static int vocab_size = 0;

void load_vocab(const char *path) {
    FILE *f = fopen(path, "r");
    char line[512];
    while (fgets(line, sizeof(line), f) && vocab_size < V) {
        int len = strlen(line);
        if (len > 0 && line[len-1] == '\n') line[len-1] = 0;
        if (line[0] == '#') continue;
        vocab[vocab_size] = malloc(len + 1);
        strcpy(vocab[vocab_size], line);
        vocab_size++;
    }
    fclose(f);
}

void load_weights(const char *path) {
    FILE *f = fopen(path, "rb");
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    weights = (float*)malloc(sz);
    fread(weights, 1, sz, f);
    fclose(f);
}

float *forward(const char *prompt) {
    int seq_len = strlen(prompt);
    float *hidden = (float*)calloc(D, sizeof(float));

    float *logits = (float*)calloc(V, sizeof(float));
    float *wte = weights;

    for (int pos = 0; pos < seq_len && pos < MAXSEQ; pos++) {
        int ch = (unsigned char)prompt[pos];
        for (int d = 0; d < D; d++) {
            hidden[d] += wte[ch * D + d] * 0.01f;
        }
    }

    for (int d = 0; d < D; d++) {
        for (int v = 0; v < V; v++) {
            logits[v] += hidden[d] * wte[v * D + d] * 0.001f;
        }
    }

    return logits;
}

int argmax(float *logits) {
    int best = 0;
    float best_val = logits[0];
    for (int i = 1; i < V; i++) {
        if (logits[i] > best_val) {
            best_val = logits[i];
            best = i;
        }
    }
    return best;
}

int main(int argc, char **argv) {
    if (argc < 4) return 1;

    load_weights(argv[1]);
    load_vocab(argv[2]);
    const char *prompt = argv[3];

    float *logits = forward(prompt);

    for (int i = 0; i < 20; i++) {
        int token = argmax(logits);
        if (token >= 0 && token < vocab_size && vocab[token]) {
            printf("%s", vocab[token]);
        }
        logits[token] = -1e9f;
    }

    return 0;
}
